import type { CalendarProps } from './calendar'

/** Display options only: the enclosing picker retains ownership of selection and form constraints. */
export type CalendarDisplayOptions = Pick<CalendarProps,
  'variant' | 'size' | 'dayShape' | 'weekStartsOn' | 'showOutsideDays' | 'fixedWeeks' | 'dayData'
>

